def calculate(s):
    stack = []
    num = 0
    op = '+'
    s = s + '+'  # sentinel to flush the last number

    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == ' ':
            continue
        else:
            if op == '+':
                stack.append(num)
            elif op == '-':
                stack.append(-num)
            elif op == '*':
                stack.append(stack.pop() * num)
            elif op == '/':
                stack.append(int(stack.pop() / num))
            op = ch
            num = 0

    return sum(stack)

